using System;using System.Drawing;using System.Reflection;using System.Windows.Forms;
class BackdropTests {
 static void Update(Widget w){for(int i=0;i<15;i++){Application.DoEvents();System.Threading.Thread.Sleep(20);}typeof(Widget).GetMethod("UpdateBackdrop",BindingFlags.Instance|BindingFlags.NonPublic).Invoke(w,null);}
 static void Check(bool condition,string message){if(!condition)throw new Exception(message);Console.WriteLine("PASS: "+message);}
 [STAThread] static void Main(){try{Application.EnableVisualStyles();using(var w=new Widget())using(var app=new Form()){w.Show();Update(w);Check(w.TopMost,"Always on top");Check(w.Opacity==1,"Desktop retains full opacity");app.FormBorderStyle=FormBorderStyle.None;app.StartPosition=FormStartPosition.Manual;app.Bounds=new Rectangle(w.Left-40,w.Top,200,120);app.Show();Update(w);Check(Math.Abs(w.Opacity-0.1)<.001,"Overlapping window sets 90 percent transparency");w.Activate();Update(w);Check(Math.Abs(w.Opacity-0.1)<.001,"Focusing widget does not mistake app for desktop");app.Location=new Point(w.Left-500,w.Top+200);Update(w);Check(w.Opacity==1,"Moving window away restores opacity");app.Bounds=new Rectangle(w.Left,w.Top,200,120);Update(w);Check(w.Opacity<.11,"Moving window back reapplies transparency");app.WindowState=FormWindowState.Minimized;Update(w);Check(w.Opacity==1,"Minimized window is ignored");app.WindowState=FormWindowState.Normal;app.Hide();Update(w);Check(w.Opacity==1,"Hidden window is ignored");w.Close();}}catch(Exception ex){Console.WriteLine(ex.GetType().Name+": "+ex.Message);Environment.ExitCode=1;}}
}

